#!/usr/bin/env node
/**
 * Import case-study documents into Sanity from case-studies.ndjson
 * (generated by `npm run migrate:case-studies`).
 *
 * Uses the local Sanity CLI login token (~/.sanity/auth.sanity) so no secret
 * is ever stored in the repo. Docs carry stable _ids (caseStudy-<slug>), so
 * re-running is idempotent: existing docs are left untouched.
 *
 * Usage:  npm run import:case-studies
 * Auth:   npx sanity login   (once, writes ~/.sanity/auth.sanity)
 */
import { readFile } from 'node:fs/promises';
import { createClient } from '@sanity/client';

const NDJSON = new URL('../case-studies.ndjson', import.meta.url);
const AUTH = `${process.env.USERPROFILE || process.env.HOME}/.sanity/auth.sanity`;

async function readProjectEnv() {
  // Single source of truth is the root .env written by the Sanity setup.
  try {
    const raw = await readFile(new URL('../.env', import.meta.url), 'utf8');
    const get = (k) => raw.match(new RegExp(`^${k}=(.*)$`, 'm'))?.[1]?.trim();
    return {
      projectId: get('VITE_SANITY_PROJECT_ID') || 'jrft938h',
      dataset: get('VITE_SANITY_DATASET') || 'production',
    };
  } catch {
    return { projectId: 'jrft938h', dataset: 'production' };
  }
}

async function readToken() {
  // 1) SANITY_TOKEN env var (token pasted for a one-off import — never stored).
  if (typeof process.env.SANITY_TOKEN === 'string' && process.env.SANITY_TOKEN.length > 20) {
    return process.env.SANITY_TOKEN.trim();
  }
  // 2) Local CLI login token (~/.sanity/auth.sanity).
  try {
    const raw = await readFile(AUTH, 'utf8');
    const json = JSON.parse(raw);
    // The CLI has used both key names across versions.
    const token = json.accessToken ?? json.token ?? json.apiToken;
    if (typeof token === 'string' && token.length > 20) return token;
    throw new Error('auth file has no access token');
  } catch (err) {
    console.error(`\n✗ Not logged in (${err.message}).`);
    console.error('  Run this once, then approve the URL it prints:\n');
    console.error('      npx --yes sanity@latest login\n');
    process.exit(1);
  }
}

async function main() {
  const { projectId, dataset } = await readProjectEnv();
  const token = await readToken();

  const raw = await readFile(NDJSON, 'utf8');
  const docs = raw
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean)
    .map((l, i) => {
      try {
        return JSON.parse(l);
      } catch {
        throw new Error(`NDJSON line ${i + 1} is not valid JSON`);
      }
    });

  if (!docs.length) {
    console.error('✗ case-studies.ndjson is empty — run `npm run migrate:case-studies` first.');
    process.exit(1);
  }

  const client = createClient({ projectId, dataset, token, apiVersion: '2024-01-01' });

  console.log(`Importing ${docs.length} case studies → ${projectId}/${dataset}\n`);

  let created = 0;
  let skipped = 0;
  for (const doc of docs) {
    const res = await client.createIfNotExists(doc);
    const isNew = res._createdAt === res._updatedAt;
    if (isNew) created++;
    else skipped++;
    console.log(`  ${isNew ? '+' : '='} ${doc.slug?.current ?? res._id}`);
  }

  const count = await client.fetch('count(*[_type == "caseStudy"])');
  console.log(`\n✓ ${created} created, ${skipped} already present — dataset now holds ${count} caseStudy doc(s).`);
}

main().catch((err) => {
  console.error(`\n✗ Import failed: ${err.message}`);
  process.exit(1);
});
